const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),z=require('node:zlib'),crypto=require('node:crypto');
const dir='docs/nationwide-expansion-20261020c/',read=n=>JSON.parse(z.gunzipSync(fs.readFileSync(dir+n+'.json.gz'))),m=read('manifest'),proof=read('source-evidence'),photos=read('selected-photos'),existing=read('existing-enrichment-proof'),E=require('../place-evidence.js'),P=require('../place-photos.js'),C=require('../place-conditions.js');
test('121 new places have exact source identities, individual licensed original photos and bounded pet evidence',()=>{
 assert.equal(m.facilities.length,121);assert.equal(m.courses.length,0);assert.equal(photos.length,125);assert.equal(new Set(photos.map(p=>p.photo.sha256)).size,125);
 let structured=0,intro=0;for(const row of m.facilities){const e=proof.find(p=>p.row.id===row.id),p=photos.find(p=>p.id===row.id),r=E.get(row);assert(r);assert.equal(row.name,e.tour.title.trim());assert.equal(row.lat,Number(e.tour.yCoord));assert.equal(row.lng,Number(e.tour.xCoord));assert.equal(P.get(row).sha256,p.photo.sha256);assert.equal(E.conditions({...row,description:'changed'}),null);assert.equal(E.intro({...row,address:'different branch'}),null);
 if(e.pet){structured++;assert.deepEqual(E.conditions(row),e.pet);}else{intro++;assert(E.intro(row));assert.equal(r.introAllowance.wholeAreaConfirmed,false);assert.equal(crypto.createHash('sha256').update(e.tour.outl).digest('hex'),r.introAllowance.originalTextSha256);assert(C.get(row).find(x=>x.label==='견종·크기 조건').value.startsWith('미확인'));}
 const html=fs.readFileSync('places/'+row.id+'/index.html','utf8');assert(html.includes(P.url(p.photo)));assert(html.includes('id="detail-conditions"'));assert(!html.includes('undefined'));
 }assert.equal(structured,21);assert.equal(intro,100);
 for(const p of photos){assert(['Type1','Type3'].includes(p.photo.rightsType));assert.equal(p.photo.rightsType,p.officialImage.cpyrhtDivCd);assert.equal(p.photo.original,p.officialImage.originimgurl.replace(/^http:/,'https:'));assert(p.photo.noCrop);require('./helpers/photo-original.cjs')(p.photo);}
});
test('translated source photos retain matching Korean identities and never override restrictive Korean image rights',()=>{
 const norm=s=>s.normalize('NFKC').replace(/[^가-힣0-9A-Za-z]/g,'').toLowerCase(),resource=s=>s.match(/\/(\d+)_image/)?.[1];const translated=photos.filter(p=>p.translatedIdentity);assert.equal(translated.length,7);
 for(const p of translated){const a=p.identity,b=p.translatedIdentity;assert(norm(b.title).includes(norm(a.title)));assert(Math.abs(Number(a.xCoord)-Number(b.xCoord))<.001);assert(Math.abs(Number(a.yCoord)-Number(b.yCoord))<.001);assert(p.photo.source.includes('contentId='+b.contentId));assert(p.photo.source.includes('langDiv='+b.lang));assert(Array.isArray(p.koreanImageResponses));const restricted=JSON.stringify(p.koreanImageResponses).match(/Type[24]/g)||[];for(const response of p.koreanImageResponses){const list=Array.isArray(response)?response:(response?.body?.items?.item||response?.response?.body?.items?.item||[]);for(const image of Array.isArray(list)?list:[]){if(['Type2','Type4'].includes(image.cpyrhtDivCd))assert.notEqual(resource(image.originimgurl||''),resource(p.photo.original));}}assert(p.officialImage.contentId===b.contentId);}
});
test('four aliases enrich existing places, preserve original camping limits and only correct one explicit map coordinate',()=>{
 assert.equal(existing.length,4);assert.equal(m.existingUpdates.length,1);for(const p of existing){assert(!m.facilities.some(r=>r.id===p.id));const r=E.get(p.rowAfter);assert(r);assert.equal(P.get(p.rowAfter).src,photos.find(x=>x.id===p.id).photo.src);assert.equal(p.rowBefore.description,p.rowAfter.description);assert.equal(p.rowBefore.address,p.rowAfter.address);if(p.recordBefore?.camping)assert.deepEqual(r.camping,p.recordBefore.camping);if(p.recordBefore?.tourNotes)assert.deepEqual(r.tourNotes,p.recordBefore.tourNotes);const html=fs.readFileSync('places/'+p.id+'/index.html','utf8');assert(html.includes(P.get(p.rowAfter).src));if(p.id==='gocamping_7212'){assert.equal(p.rowAfter.lat,37.7805905193);assert.equal(p.rowAfter.lng,127.2884838499);assert(r.locationCorrection);}else{assert.equal(p.rowBefore.lat,p.rowAfter.lat);assert.equal(p.rowBefore.lng,p.rowAfter.lng);}}
 const small=existing.find(x=>x.id==='gocamping_8038');assert(JSON.stringify(E.get(small.rowAfter).camping).includes('소형견'));
});
